(function(){try{var p=window.USER_PREFERENCES||{};var lm=localStorage.getItem('moe_motion');if((lm!==null?lm==='0':p.effects_enabled===false)){document.documentElement.classList.add('motion-off');}var le=localStorage.getItem('blog_reading_prefs');var eye=p.eye_protection,am=p.amoled_dark;if(le){try{var rp=JSON.parse(le);if(rp.eyeProtection)eye=true;if(rp.amoled)am=true;}catch(e){}}if(eye)document.body.classList.add('eye-protection');if(am)document.body.classList.add('amoled-dark');}catch(e){}})();